const j = items?.[0]?.json ?? {};
const defaultSeed = [
  'https://www.melnick.com.br/enterprise/go-bom-fim-2/',
  'https://www.melnick.com.br/enterprise/high-garden-rio-branco/',
  'https://www.melnick.com.br/enterprise/go-home-design/'
];

const seeded = Array.isArray(j.seedUrls) && j.seedUrls.length ? j.seedUrls : defaultSeed;
const statusCode = Number(j.statusCode ?? 200);
const body = typeof j.body === 'string' ? j.body : JSON.stringify(j.body ?? '');
const isTimeoutOrEmpty = statusCode >= 500 || body.length < 500;

if (isTimeoutOrEmpty) {
  return seeded.map((empreendimentoUrl, i) => ({
    json: {
      indice: i + 1,
      totalLinks: seeded.length,
      empreendimentoUrl,
      origem: 'fallback_seed_urls',
      motivoFallback: `status=${statusCode}`
    }
  }));
}

const regex = /https:\/\/www\.melnick\.com\.br\/enterprise\/[A-Za-z0-9\-_/]+/gi;
const urls = new Set();
while (true) {
  const m = regex.exec(body);
  if (!m) break;
  const clean = m[0].replace(/["'<>]/g, '').replace(/\/$/, '') + '/';
  urls.add(clean);
}

const links = [...urls].sort();
if (!links.length) {
  return seeded.map((empreendimentoUrl, i) => ({
    json: {
      indice: i + 1,
      totalLinks: seeded.length,
      empreendimentoUrl,
      origem: 'fallback_seed_urls_sem_match',
      motivoFallback: 'sem_links_no_html'
    }
  }));
}

return links.map((empreendimentoUrl, i) => ({
  json: {
    indice: i + 1,
    totalLinks: links.length,
    empreendimentoUrl,
    origem: 'html_empreendimentos'
  }
}));

const empreendimentoUrl = $json.empreendimentoUrl;
const raw = $json.body ?? $json.data ?? $json.response ?? '';
const html = typeof raw === 'string' ? raw : JSON.stringify(raw || '');

const titleMatch = html.match(/<h1[^>]*>(.*?)<\/h1>/is);
const nome = titleMatch ? titleMatch[1].replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim() : null;

const imgRegex = /https?:\/\/[^\s"'<>]+\.(?:jpg|jpeg|png|webp|gif)(?:\?[^"'<>\s]+)?/gi;
const all = new Set();
while (true) {
  const m = imgRegex.exec(html);
  if (!m) break;
  const u = m[0].replace(/&amp;/g, '&');
  if (u.includes('data:image')) continue;
  all.add(u);
}

const rawImageUrls = [...all].sort();
const plantas = rawImageUrls.filter((u) => /planta|floor|tipologia|implantacao|implanta/i.test(u));
const galeria = rawImageUrls.filter((u) => /galeria|gallery|fachada|decorado|interna|externa|lazer|piscina|rooftop|living|suite|dormitorio/i.test(u) && !plantas.includes(u));
const caracteristicas = rawImageUrls.filter((u) => /icone|icon|caracteristica|feature|amenit/i.test(u) && !plantas.includes(u) && !galeria.includes(u));
const outras = rawImageUrls.filter((u) => !plantas.includes(u) && !galeria.includes(u) && !caracteristicas.includes(u));

const aiPrompt = [
  'Voce recebera um empreendimento e uma lista de URLs de imagens.',
  'Classifique APENAS em JSON valido.',
  'Estrutura obrigatoria:',
  '{"nome":"...","url":"...","galeria":[],"plantas":[],"caracteristicas":[],"outras":[]}',
  'Regras:',
  '- Nao invente URLs.',
  '- Nao repita URLs.',
  '- Se tiver duvida, coloque em outras.',
  '- Responda somente JSON sem markdown.',
  '',
  `nome: ${nome ?? ''}`,
  `url: ${empreendimentoUrl}`,
  '',
  'urls:',
  JSON.stringify(rawImageUrls)
].join('\n');

return [{ json: { nome, url: empreendimentoUrl, rawImageUrls, heuristica: { galeria, plantas, caracteristicas, outras }, aiPrompt } }];

const src = $json.output ?? $json.text ?? '';
let parsed = null;

try {
  parsed = JSON.parse(src);
} catch (e) {
  const maybeJson = String(src).match(/\{[\s\S]*\}/);
  if (maybeJson) {
    try {
      parsed = JSON.parse(maybeJson[0]);
    } catch (e2) {
      parsed = null;
    }
  }
}

const heuristica = $item(0).$node['Extrair imagens + montar prompt'].json.heuristica;
const base = $item(0).$node['Extrair imagens + montar prompt'].json;

if (!parsed || typeof parsed !== 'object') {
  return [{
    json: {
      nome: base.nome,
      url: base.url,
      galeria: heuristica.galeria,
      plantas: heuristica.plantas,
      caracteristicas: heuristica.caracteristicas,
      outras: heuristica.outras,
      origemClassificacao: 'heuristica_fallback'
    }
  }];
}

const norm = (v) => Array.isArray(v) ? [...new Set(v.filter(Boolean))] : [];
return [{
  json: {
    nome: parsed.nome ?? base.nome,
    url: parsed.url ?? base.url,
    galeria: norm(parsed.galeria),
    plantas: norm(parsed.plantas),
    caracteristicas: norm(parsed.caracteristicas),
    outras: norm(parsed.outras),
    origemClassificacao: 'gemini'
  }
}];
